// ═══ Normaliza el aviso que manda Supabase ═══
const cfg = $('Configuracion').first().json;
const tabla = $('Verificar origen').first().json.tabla;
const filas = $input.first().json.body;
const registro = Array.isArray(filas) && filas.length === 1 ? filas[0] : null;
if (!registro || !tabla) return [];

let tipo, url;
if (tabla === 'solicitudes') {
  tipo = 'solicitud';
  url = cfg.supabaseUrl + '/rest/v1/proveedores'
      + '?rubro=eq.' + encodeURIComponent(registro.servicio_necesitado)
      + '&demo=eq.false'
      + '&order=precio_desde.asc';
} else if (tabla === 'proveedores') {
  tipo = 'proveedor';
  url = cfg.supabaseUrl + '/rest/v1/solicitudes'
      + '?servicio_necesitado=eq.' + encodeURIComponent(registro.rubro)
      + '&estado=eq.pendiente'
      + '&demo=eq.false';
} else { return []; }

return [{ json: { tipo, registro, url } }];

// ═══ Aplica las reglas de matching ═══
const cfg = $('Configuracion').first().json;
const ev  = $('Preparar consulta').first().json;

const TOL    = Number(cfg.tolerancia);
const MAX    = Number(cfg.maxSugeridos);
const REMOTO = 'Todo el país (remoto)';

// Zonas que se consideran cercanas entre sí.
// Un cliente de CABA puede recibir proveedores de GBA, y viceversa.
const REGIONES = {
  AMBA:      ['CABA','GBA Norte','GBA Oeste','GBA Sur'],
  Centro:    ['Buenos Aires (interior)','Córdoba','Santa Fe','Entre Ríos'],
  Cuyo:      ['Mendoza'],
  NOA:       ['Tucumán','Salta'],
  NEA:       ['Chaco','Corrientes','Misiones'],
  Patagonia: ['Neuquén','Río Negro','Chubut','Santa Cruz']
};

function regionDe(z) {
  for (const r in REGIONES) if (REGIONES[r].includes(z)) return r;
  return null;
}

// 0 = misma zona · 1 = remoto · 2 = zona cercana · null = no califica
function cercania(zonaCliente, zonaProv) {
  if (zonaProv === zonaCliente) return 0;
  if (zonaProv === REMOTO)      return 1;
  const a = regionDe(zonaCliente), b = regionDe(zonaProv);
  if (a && b && a === b)        return 2;
  return null;
}

const candidatos = $input.all().map(i => i.json);

function califica(sol, prov) {
  if (prov.rubro !== sol.servicio_necesitado) return false;
  if (cercania(sol.zona, prov.zona) === null) return false;
  return Number(prov.precio_desde) <= Number(sol.presupuesto) * (1 + TOL);
}

// Orden: primero por cercanía, después los que entran en presupuesto,
// y dentro de cada grupo del más barato al más caro.
function ordenar(sol, lista) {
  return lista.slice().sort((a, b) => {
    const ca = cercania(sol.zona, a.zona), cb = cercania(sol.zona, b.zona);
    if (ca !== cb) return ca - cb;
    const ea = Number(a.precio_desde) > Number(sol.presupuesto);
    const eb = Number(b.precio_desde) > Number(sol.presupuesto);
    if (ea !== eb) return ea ? 1 : -1;
    return Number(a.precio_desde) - Number(b.precio_desde);
  });
}

const matches = [], ids = [], pares = [];

if (ev.tipo === 'solicitud') {
  const sol = ev.registro;
  const aptos = ordenar(sol, candidatos.filter(p => califica(sol, p))).slice(0, MAX);
  aptos.forEach(p => {
    matches.push({ solicitud_id: sol.id, proveedor_id: p.id, estado: 'sugerido' });
    pares.push({ sol, prov: p });
  });
  if (aptos.length) ids.push(sol.id);
} else {
  const prov = ev.registro;
  candidatos.forEach(sol => {
    if (califica(sol, prov)) {
      matches.push({ solicitud_id: sol.id, proveedor_id: prov.id, estado: 'sugerido' });
      pares.push({ sol, prov });
      ids.push(sol.id);
    }
  });
}

if (!matches.length) return [];

return [{ json: {
  matches, pares,
  idsSolicitudes: [...new Set(ids)],
  cantidad: matches.length,
  disparador: ev.tipo
} }];

// ═══ Arma un mail por destinatario ═══
const cfg   = $('Configuracion').first().json;
const pares = ($('Calcular matches').first().json.pares) || [];
if (!pares.length) return [];

const pesos = n => '$' + Number(n).toLocaleString('es-AR');
const esc = t => String(t == null ? '' : t)
  .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');

const V = '#1E5D49', OSC = '#0C2620', GRIS = '#68766F', LIN = '#E0DCD0';

function envoltura(titulo, cuerpo) {
  const cta = cfg.appUrl
    ? '<tr><td style="padding:0 28px 30px"><a href="' + cfg.appUrl + '" style="display:inline-block;background:' + V + ';color:#fff;text-decoration:none;font-weight:600;font-size:15px;padding:13px 26px;border-radius:8px">Abrir la app</a></td></tr>'
    : '<tr><td style="padding:0 28px 30px;color:' + GRIS + ';font-size:13px">Entrá a la app para responder.</td></tr>';
  return '<!DOCTYPE html><html><body style="margin:0;background:#F2F0E9;font-family:Helvetica,Arial,sans-serif">'
    + '<table width="100%" cellpadding="0" cellspacing="0"><tr><td align="center" style="padding:26px 12px">'
    + '<table width="100%" style="max-width:560px;background:#FCFBF8;border-radius:10px;overflow:hidden;border:1px solid ' + LIN + '" cellpadding="0" cellspacing="0">'
    + '<tr><td style="background:' + OSC + ';padding:22px 28px">'
    + '<div style="color:#9AA69B;font-size:10px;letter-spacing:2.6px;text-transform:uppercase">Marketplace de servicios</div>'
    + '<div style="color:#FCFBF8;font-size:21px;font-weight:bold;margin-top:8px;line-height:1.25">' + titulo + '</div>'
    + '</td></tr>' + cuerpo + cta
    + '<tr><td style="padding:16px 28px;background:#F2F0E9;color:' + GRIS + ';font-size:11.5px;border-top:1px solid ' + LIN + '">Recibís este aviso porque tenés una cuenta activa en el marketplace.</td></tr>'
    + '</table></td></tr></table></body></html>';
}

const fila = (k, v) => '<tr><td style="padding:9px 0;border-bottom:1px solid ' + LIN + ';color:' + GRIS + ';font-size:13.5px">' + k
  + '</td><td style="padding:9px 0;border-bottom:1px solid ' + LIN + ';text-align:right;font-size:13.5px;font-weight:bold">' + v + '</td></tr>';

const salida = [];

// ── 1. Aviso a cada proveedor ──
pares.forEach(({ sol, prov }) => {
  const cuerpo = '<tr><td style="padding:24px 28px 8px">'
    + '<p style="margin:0 0 16px;font-size:15px;line-height:1.6">Hola ' + esc(prov.nombre) + ', alguien está buscando justo lo que ofrecés.</p>'
    + '<div style="background:#F2F0E9;border-radius:8px;padding:16px;font-size:14px;line-height:1.6;color:#0E1815">' + esc(sol.descripcion) + '</div>'
    + '<table width="100%" cellpadding="0" cellspacing="0" style="margin-top:18px">'
    + fila('Servicio', esc(sol.servicio_necesitado))
    + fila('Zona', esc(sol.zona))
    + fila('Presupuesto', pesos(sol.presupuesto))
    + fila('Urgencia', esc(sol.urgencia))
    + '</table>'
    + '<p style="margin:18px 0 0;font-size:13px;color:' + GRIS + '">Respondé rápido: le sugerimos hasta 3 proveedores y suele elegir al primero que contesta.</p>'
    + '</td></tr>';
  salida.push({
    para: prov.email,
    nombre: prov.nombre,
    asunto: 'Un cliente busca ' + sol.servicio_necesitado + ' en ' + sol.zona,
    html: envoltura('Te llegó un cliente', cuerpo)
  });
});

// ── 2. Un aviso por cliente, agrupando sus proveedores ──
const porSol = {};
pares.forEach(({ sol, prov }) => {
  if (!porSol[sol.id]) porSol[sol.id] = { sol, provs: [] };
  porSol[sol.id].provs.push(prov);
});

Object.keys(porSol).forEach(k => {
  const { sol, provs } = porSol[k];
  const tarjetas = provs.map(p => {
    const sobre = Number(p.precio_desde) > Number(sol.presupuesto);
    const chapa = sobre
      ? '<span style="font-size:10px;color:#8A6E10;border:1px solid rgba(201,162,39,.6);border-radius:99px;padding:3px 9px">' + Math.round((Number(p.precio_desde)/Number(sol.presupuesto)-1)*100) + '% sobre presupuesto</span>'
      : '<span style="font-size:10px;color:' + V + ';border:1px solid ' + V + ';border-radius:99px;padding:3px 9px">Entra en presupuesto</span>';
    return '<div style="border:1px solid ' + LIN + ';border-radius:8px;padding:15px;margin-bottom:10px">'
      + '<div style="font-size:16px;font-weight:bold;margin-bottom:7px">' + esc(p.nombre) + '</div>' + chapa
      + '<div style="margin-top:10px;font-size:13.5px;color:' + GRIS + ';line-height:1.55">' + esc(p.descripcion) + '</div>'
      + '<div style="margin-top:10px;font-size:13px"><b>' + pesos(p.precio_desde) + ' – ' + pesos(p.precio_hasta) + '</b> · ' + esc(p.zona) + ' · ' + esc(p.disponibilidad) + '</div>'
      + '</div>';
  }).join('');

  const plural = provs.length === 1 ? 'proveedor' : 'proveedores';
  const cuerpo = '<tr><td style="padding:24px 28px 8px">'
    + '<p style="margin:0 0 18px;font-size:15px;line-height:1.6">Hola ' + esc(sol.nombre_cliente) + ', encontramos ' + provs.length + ' ' + plural + ' para tu pedido de ' + esc(sol.servicio_necesitado) + ' en ' + esc(sol.zona) + '.</p>'
    + tarjetas
    + '<p style="margin:16px 0 0;font-size:13px;color:' + GRIS + '">Ya podés escribirles desde el chat de la app y pedirles presupuesto.</p>'
    + '</td></tr>';

  salida.push({
    para: sol.email_cliente,
    nombre: sol.nombre_cliente,
    asunto: 'Encontramos ' + provs.length + ' ' + plural + ' para tu pedido',
    html: envoltura('Tenemos ' + plural + ' para vos', cuerpo)
  });
});

return salida.filter(a => a.para).map(a => ({ json: a }));

// Solo se acepta el aviso que manda la base de datos (trae el encabezado secreto).
// Del aviso se usa solamente la tabla y el id: el registro se vuelve a leer de
// la base, asi nadie puede inventar un pedido o un proveedor.
const w = $('Aviso de Supabase').first().json;
const h = w.headers || {};
if (h['x-tratto-secreto'] !== '<SECRETO_EN_N8N>') return [];
const p = w.body || {};
const id = Number(p.record && p.record.id);
if (!Number.isInteger(id) || id <= 0) return [];
const cfg = $('Configuracion').first().json;
let url;
if (p.table === 'solicitudes') url = cfg.supabaseUrl + '/rest/v1/solicitudes?id=eq.' + id + '&estado=eq.pendiente&demo=eq.false&select=*';
else if (p.table === 'proveedores') url = cfg.supabaseUrl + '/rest/v1/proveedores?id=eq.' + id + '&demo=eq.false&select=*';
else return [];
return [{ json: { tabla: p.table, url } }];
